import{_ as e,o,c as t,K as i}from"./chunks/framework.0517f38e.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start/introduction.md","filePath":"quick-start/introduction.md"}'),n={name:"quick-start/introduction.md"};function r(s,a,l,c,h,d){return o(),t("div",null,a[0]||(a[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><h2 id="what-is-scs-chain" tabindex="-1">What is SCS Chain? <a class="header-anchor" href="#what-is-scs-chain" aria-label="Permalink to &quot;What is SCS Chain?&quot;">​</a></h2><p>SCS Chain is an infrastructure that helps developers and operators build and operate their blockchain services as internal value systems, providing services to a large number of users. The primary mission of SCS Chain is to enable any project developer to deploy their blockchain applications using its unique specifications. The technical goal of SCS Chain is to achieve transaction processing speeds (TPS) of up to 100,000 or even a million on the master, meeting the requirements of most applications, especially in gaming and social scenarios. It is understood that Layer 2 solutions are not the best way to enhance the performance of the master chain, as they can lead to excessive fragmentation of users, developers, and ecosystem funds, which is detrimental to ecological development. Therefore, SCS Chain prioritizes enhancing master chain TPS as its key technical objective.</p><h2 id="main-features" tabindex="-1">Main Features <a class="header-anchor" href="#main-features" aria-label="Permalink to &quot;Main Features&quot;">​</a></h2><ol><li><p><strong>Highly Scalable and Low Cost</strong><br> Supports modular development, allowing for the free combination of on-chain functions, providing a richer set of master chain features compared to Ethereum. It is 100% EVM compatible, lowering the development barriers for ecosystem developers while keeping transaction costs low.</p></li><li><p><strong>Support for SuperEx</strong><br> Seamless integration with SuperEx products.</p></li><li><p><strong>Security</strong><br> Provides reliable smart contract auditing services, furthering the vision of building a trustless ecosystem.</p></li><li><p><strong>On-Chain Governance</strong><br> Offers a rich set of on-chain governance features that are fully decentralized, allowing the community to participate in decision-making.</p></li><li><p><strong>NPOS Consensus</strong><br> Utilizes NPOS consensus, making nodes more decentralized, which contributes to building a more secure and censorship-resistant network.</p></li></ol><h2 id="nominated-proof-of-stake-npos" tabindex="-1">Nominated Proof of Stake (NPOS) <a class="header-anchor" href="#nominated-proof-of-stake-npos" aria-label="Permalink to &quot;Nominated Proof of Stake (NPOS)&quot;">​</a></h2><p>NPoS is a variant of the standard Proof of Stake (PoS) model. Compared to PoS, it enhances security, community participation, and decentralization. It is a fairer and more flexible consensus mechanism.</p><h2 id="economic-model" tabindex="-1">Economic Model <a class="header-anchor" href="#economic-model" aria-label="Permalink to &quot;Economic Model&quot;">​</a></h2><p>The initial total supply of SCS Chain is 1 billion, with a small percentage of inflation occurring each year. Specific parameters will be announced before the launch or updated through community governance after the launch.</p><h3 id="validators-and-nominators" tabindex="-1">Validators and Nominators <a class="header-anchor" href="#validators-and-nominators" aria-label="Permalink to &quot;Validators and Nominators&quot;">​</a></h3><p>In NPoS, there are two main roles: validators and nominators. Validators are responsible for validating transactions and maintaining the blockchain, while nominators stake tokens to specific validators, aligning their interests. Nominators typically base their staking on the performance and credibility of the validators. Validators can set a commission rate for their nodes.</p><h3 id="staking-and-rewards" tabindex="-1">Staking and Rewards <a class="header-anchor" href="#staking-and-rewards" aria-label="Permalink to &quot;Staking and Rewards&quot;">​</a></h3><p>Staking is a fundamental feature of NPoS. Participants lock up a certain amount of cryptocurrency to become nominators. Both validators and nominators can earn rewards proportional to their stake from block rewards and transaction fees, incentivizing active and honest participation in the network.</p><h3 id="penalty-mechanism" tabindex="-1">Penalty Mechanism <a class="header-anchor" href="#penalty-mechanism" aria-label="Permalink to &quot;Penalty Mechanism&quot;">​</a></h3><p>If a validator acts maliciously or incompetently, a portion of their tokens (along with their nominators&#39; tokens) may be slashed, resulting in permanent loss of circulation. There is no room for manipulation by miners (validators).</p><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><h3 id="_1-0-0-q4-2024" tabindex="-1"><strong>1.0.0 Q4 2024</strong> <a class="header-anchor" href="#_1-0-0-q4-2024" aria-label="Permalink to &quot;**1.0.0 Q4 2024**&quot;">​</a></h3><ol><li>Launch of Testnet</li><li>Launch of Mainnet</li><li>Block Explorer</li></ol><h3 id="_1-2-0-q1-2025" tabindex="-1"><strong>1.2.0 Q1 2025</strong> <a class="header-anchor" href="#_1-2-0-q1-2025" aria-label="Permalink to &quot;**1.2.0 Q1 2025**&quot;">​</a></h3><ol><li>Ethereum Cross-Chain Bridge</li><li>Support for SNS (SCS Chain On-Chain Domain Service)</li><li>Decentralized Exchange</li></ol><h3 id="_1-3-0-q2-2025" tabindex="-1"><strong>1.3.0 Q2 2025</strong> <a class="header-anchor" href="#_1-3-0-q2-2025" aria-label="Permalink to &quot;**1.3.0 Q2 2025**&quot;">​</a></h3><ol><li>Support for XCM Protocol</li><li>Integration into the Polkadot ecosystem, sharing Polkadot network security</li></ol><h3 id="_1-4-0-q3-2025" tabindex="-1"><strong>1.4.0 Q3 2025</strong> <a class="header-anchor" href="#_1-4-0-q3-2025" aria-label="Permalink to &quot;**1.4.0 Q3 2025**&quot;">​</a></h3><ol><li>Super Chain, connecting Ethereum, Bitcoin, and more public chain ecosystems</li><li>Support for multi-language development of smart contracts</li></ol><h3 id="_2-0-0-q4-2025" tabindex="-1"><strong>2.0.0 Q4 2025</strong> <a class="header-anchor" href="#_2-0-0-q4-2025" aria-label="Permalink to &quot;**2.0.0 Q4 2025**&quot;">​</a></h3><ol><li>Support for JAM Protocol, achieving TPS of 100,000 or even a million</li><li>Support for parallel transactions</li><li>Decentralized Identity</li></ol>',26)]))}const u=e(n,[["render",r]]);export{p as __pageData,u as default};
